parameters.jsCode:
const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const token = headers['x-filtra-report-token'] ?? headers['X-Filtra-Report-Token'];
const expected = $env.N8N_WHATSAPP_REPORT_TOKEN;

if (!expected || !token || token !== expected) {
  return [{json:{ok:false,status:401,error:'Unauthorized'}}];
}
if (!body || !body.cliente_id || !body.periodo || !Array.isArray(body.destinatarios)) {
  return [{json:{ok:false,status:400,error:'Invalid payload'}}];
}
if (body.destinatarios.length === 0) {
  return [{json:{ok:false,status:400,error:'No recipients'}}];
}
if (body.destinatarios.length > 20) {
  return [{json:{ok:false,status:400,error:'Too many recipients'}}];
}
return [{json:{
  ok:true,
  cliente_id:String(body.cliente_id),
  periodo:String(body.periodo),
  idempotency_key:String(body.idempotency_key || `relatorio:${body.cliente_id}:${body.periodo}`),
  relatorio:body.relatorio ?? body.report ?? null,
  destinatarios:body.destinatarios
}}];

const key = $json.idempotency_key;

if (!key) {
  return [{
    json: {
      ...$json,
      duplicate: false,
      status: 'missing_idempotency_key'
    }
  }];
}

return [{
  json: {
    ...$json,
    duplicate: false,
    status: 'new'
  }
}];

const r = $json.relatorio;
if (r == null) {
  return [{json:{...$json,message:'',report_available:false}}];
}
let message = '';
if (typeof r === 'string') {
  message = r;
} else if (typeof r === 'object') {
  // Only serialize data supplied by the backend. No AI, no invented content.
  const labels = {
    score:'Score', total:'Total', variation:'Variação', previous_score:'Score anterior',
    positive_rate:'Taxa positiva', crises_24h:'Crises 24h', treated:'Tratadas',
    pending:'Pendentes', trend:'Tendência', positive:'Positivas', negative:'Negativas'
  };
  const lines = Object.entries(r)
    .filter(([_,v]) => v !== null && v !== undefined && typeof v !== 'object')
    .map(([k,v]) => `${labels[k] || k}: ${v}`);
  message = lines.join('\n');
  if (!message) message = JSON.stringify(r);
} else {
  message = String(r);
}
return [{json:{...$json,message,report_available:Boolean(message)}}];

const recipients = $json.destinatarios || [];
return recipients.map((r,index)=>({
  json:{
    cliente_id:$json.cliente_id,
    periodo:$json.periodo,
    idempotency_key:$json.idempotency_key,
    message:$json.message,
    recipient_index:index,
    channel:String(r.channel || '').toLowerCase(),
    destination:r.destination ?? r.phone ?? r.email ?? r.address ?? null
  }
}));

