const items = $input.all();
const results = items.map((item, i) => {
  const d = item.json || {};
  const input = d.json ?? d;
  return {
    channel: input.channel ?? null,
    destination: input.destination ?? null,
    status: d.error ? 'failed' : 'sent',
    ok: !d.error,
    error: d.error?.message ?? null,
    provider_response: d
  };
});
const failed = results.filter(r => !r.ok).length;
return [{
  json: {
    ok: failed === 0,
    status: failed === 0 ? 'completed' : 'partial_failure',
    cliente_id: results[0]?.provider_response?.cliente_id ?? null,
    periodo: results[0]?.provider_response?.periodo ?? null,
    idempotency_key: results[0]?.provider_response?.idempotency_key ?? null,
    total: results.length,
    sent: results.filter(r=>r.ok).length,
    failed,
    results
  }
}];
